import fs from"fs";import path from"path";import sharp from"sharp";const inputDir="./future",outputDir="./future/optimized";fs.mkdirSync(outputDir,{recursive:!0}),fs.readdirSync(inputDir).forEach((r=>{if(r.match(/\.(jpg|jpeg|png)$/i)){const i=path.join(inputDir,r),t=path.join(outputDir,`${path.parse(r).name}.webp`);sharp(i).resize({width:1050}).webp({quality:85}).toFile(t).then((()=>console.log(`✅ Optimized: ${r}`))).catch((i=>console.error(`❌ Error optimizing ${r}:`,i)))}}));